#include "../src/page_decoration.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace page_decoration;auto outline=heart();assert(outline.size()==64);for(size_t i=0;i<64;++i){auto a=outline[i],b=outline[(64-i)%64];assert(a.x>=0&&a.x<=1&&a.y>=0&&a.y<=1);assert(std::abs(a.x+b.x-1)<1e-12&&std::abs(a.y-b.y)<1e-12);}assert(outline[32].y>outline[0].y&&std::abs(outline[32].x-.5)<1e-12);assert(symbol("Christmas Day (observed)")==Tree);assert(symbol("New Year's Day")==Firework);assert(symbol("Thanksgiving")==Leaf);assert(symbol("Valentine's Day")==Heart);assert(symbol("Martin Luther King Jr. Day")==Star);assert(countdown(0)=="TODAY"&&countdown(1)=="TOMORROW"&&countdown(365)=="365 DAYS");assert(std::string(month(0))=="---"&&std::string(month(12))=="DEC");assert(dayOfYear({2024,12,31,0,0,0})==366&&dayOfYear({2026,12,31,0,0,0})==365);assert(monthYear({2026,11,15,0,0,0})=="November 2026");std::cout<<"PASS: holiday decoration categories, observed names, countdown boundaries and clock date badges including leap-year day counts.\n";}
